const {test,before,after}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),http=require('node:http');
const {chromium}=require('playwright');let browser,server,url;const root=path.resolve(__dirname,'..');
const harness=`<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/practice-tools.css"><link rel="stylesheet" href="/neuro-record.css"><link rel="stylesheet" href="/ophthalmic-record.css"><style>@font-face{font-family:Pretendard;src:url(/pretendard-variable-1.3.9.woff2)}body{font-family:Pretendard,sans-serif;margin:14px;background:#f5f7fb}</style><main id="root"></main><script src="/ophthalmic-record.js"></script><script>
window.state={scope:'test:owner',canEdit:true,records:JSON.parse(sessionStorage.getItem('mock-records')||'[]'),requests:[],keys:{},imageData:{},fail:false};
const patient={id:'p1',name:'합성 환자',species:'dog',breed:'합성 품종',sex:'male',neutered:'yes',birthDate:'2020-01-01',latestWeightKg:5,guardianName:'합성 보호자',chartNumber:'TEST-101'};
const persist=()=>sessionStorage.setItem('mock-records',JSON.stringify(state.records));
function images(d,id,revision){for(const im of d.images){if(im.dataUrl){state.imageData[id+':'+im.id]=im.dataUrl;delete im.dataUrl;im.imageRevision=revision;}}return d;}
window.api=async(p,o={})=>{state.requests.push({p,...o});if(state.fail)throw Error('합성 네트워크 실패');if(p.startsWith('/patient-directory'))return {patients:[patient],pagination:{hasNext:false}};if(p.endsWith('/members'))return {members:[{id:'u',display_name:'시험 검사자'}]};const b=o.body?JSON.parse(o.body):null;if(p.endsWith('/workflows')){state.workflows??=[];if(o.method==='POST'){const w={id:'w'+state.workflows.length,body:b.body};state.workflows.push(w);return {ok:true,id:w.id};}return {items:state.workflows};}
if(p.includes('/ophthalmic?')){const q=new URL('https://test'+p).searchParams;if(state.pages)return state.pages[q.get('cursor')||'first'];return {items:state.records.filter(r=>!r.body.deleted&&(!q.get('patientId')||r.patient_id===q.get('patientId'))&&(!q.get('status')||r.body.ophthalmicChart.clinicalStatus===q.get('status'))&&(!q.get('q')||(r.patient.name+r.body.ophthalmicChart.diagnosis).includes(q.get('q')))).map(r=>({id:r.id,patient:{...r.patient,...r.body.ophthalmicChart.patient},date:r.body.ophthalmicChart.date,diagnosis:r.body.ophthalmicChart.diagnosis,clinicalStatus:r.body.ophthalmicChart.clinicalStatus})),next:null};}
if(b?.requestKey&&state.keys[b.requestKey])return {...state.keys[b.requestKey],replayed:true};
if(p.endsWith('/cases')&&o.method==='POST'){const r={id:'e'+(state.records.length+1),revision:1,patient_id:b.patientId||'',patient:b.patientId?patient:{...b.quickPatient,species:b.species},body:{species:b.species,category:'ophthalmic',previousId:b.previousId,ophthalmicChart:images(structuredClone(b.ophthalmicChart),'e'+(state.records.length+1),1)}};state.records.push(r);persist();const out={id:r.id,revision:1,ophthalmicChart:structuredClone(r.body.ophthalmicChart)};state.keys[b.requestKey]=out;if(state.loseResponse){state.loseResponse=false;throw Error('합성 응답 유실');}return out;}
const id=p.split('/cases/')[1]?.split(/[/?]/)[0],r=state.records.find(x=>x.id===id);if(!r||r.body.deleted)throw Error('기록 없음');if(o.method==='POST'){if(b.revision!==r.revision)throw Object.assign(Error('다른 직원이 기록했습니다.'),{status:409});if(b.kind==='case.delete')r.body.deleted=true;else {if(r.body.ophthalmicChart.clinicalStatus==='complete'&&b.data.clinicalStatus==='complete'&&JSON.stringify(r.body.ophthalmicChart)!==JSON.stringify(b.data))b.data.clinicalStatus='amended';r.body.ophthalmicChart=images(structuredClone(b.data),id,r.revision+1);}r.revision++;persist();const out={id:r.id,revision:r.revision,ophthalmicChart:structuredClone(r.body.ophthalmicChart)};state.keys[b.requestKey]=out;if(state.loseResponse){state.loseResponse=false;throw Error('합성 응답 유실');}return out;}
if(p.includes('/ophthalmic-images'))return {dataUrl:state.imageData[id+':'+new URL('https://test'+p).searchParams.get('id')]};return {item:structuredClone(r),canManage:state.canEdit};};
window.opts={ready:()=>true,identity:()=>state.scope,can:k=>k!=='records.edit'||state.canEdit,medical:()=>state.canEdit,clinicalManage:()=>state.canEdit,request:(p,o)=>api(p,o),clinicName:()=> '합성 시험 병원'};window.view=OphthalmicRecord.mount(document.querySelector('#root'),opts);view.open();</script>`;
before(async()=>{server=http.createServer((req,res)=>{const name=new URL(req.url,'http://local').pathname.slice(1);if(!name){res.setHeader('Content-Type','text/html; charset=utf-8');res.end(harness);return;}const file=path.join(root,name);if(!fs.existsSync(file)){res.writeHead(404);res.end();return;}res.setHeader('Content-Type',name.endsWith('.html')?'text/html; charset=utf-8':name.endsWith('.css')?'text/css':name.endsWith('.woff2')?'font/woff2':'application/javascript');res.end(fs.readFileSync(file));});await new Promise(r=>server.listen(0,'127.0.0.1',r));url='http://127.0.0.1:'+server.address().port;browser=await chromium.launch({executablePath:process.env.HQ_TEST_BROWSER,headless:true});});
after(async()=>{await browser?.close();server.closeAllConnections();await new Promise(r=>server.close(r));});
async function page(width=1440){const p=await browser.newPage({viewport:{width,height:950}});p.setDefaultTimeout(7000);p.on('dialog',d=>d.accept());await p.goto(url);await p.locator('[data-act=new]').waitFor();return p;}
async function tab(p,name){await p.locator('[data-jump=er-'+name+']').click();}
async function quick(p){await p.locator('[data-act=new]').click();await p.locator('[data-identity]').fill('합성 안과환자');await p.locator('[data-species]').selectOption('cat');await p.locator('[data-field="patient.guardianName"]').fill('시험 보호자');await p.locator('[data-field="patient.chartNumber"]').fill('Q-TEST');}
async function save(p){await p.locator('[data-act=save]').click();await p.waitForFunction(()=>document.querySelector('[data-act=save]')?.textContent==='저장 완료');}
async function begin(p){await quick(p);await save(p);}
async function registered(p){await p.locator('[data-act=new]').click();await p.locator('[data-patient-query]').fill('합성');await p.locator('[data-patient-form] button').click();await p.locator('[data-pick]').click();await save(p);}
test('quick eye exam records OD and OS separately, zero is preserved and untested stays absent',async()=>{const p=await page();await quick(p);await p.locator('[data-field="od.stt"]').fill('0');await p.locator('[data-field="os.stt"]').fill('15');await p.locator('[data-field="od.plrDirect"]').selectOption('present');await save(p);const d=await p.evaluate(()=>state.records[0].body.ophthalmicChart);assert.equal(d.od.stt,0);assert.equal(d.os.stt,15);assert.equal(d.od.vision,undefined);assert.equal(d.os.iop,undefined);await p.reload();await p.locator('[data-field="od.stt"]').waitFor();assert.equal(await p.locator('[data-field="od.stt"]').inputValue(),'0');await p.close();});
test('registered identity loads date of birth, breed, sex and measured weight',async()=>{const p=await page();await registered(p);assert.match(await p.locator('.er-head').innerText(),/합성 품종.*중성화 수컷.*6세.*5 kg/);assert.equal(await p.locator('[data-field="patient.birthDate"]').inputValue(),'2020-01-01');assert.equal(await p.locator('[data-sex]').inputValue(),'male:yes');await p.close();});
test('lesion location, dimensions and prescriptions retain laterality through save',async()=>{const p=await page();await begin(p);await tab(p,'maps');await p.locator('[data-eye-map=od]').press('Enter');await p.locator('[data-lesion="0.type"]').fill('시험 궤양');await p.locator('[data-lesion="0.widthMm"]').fill('2');await p.locator('[data-lesion="0.heightMm"]').fill('3');await tab(p,'plan');await p.locator('[data-act=add-rx]').click();await p.locator('[data-rx="0.eye"]').selectOption('os');await p.locator('[data-rx="0.name"]').fill('시험 점안약');await p.locator('[data-rx="0.amount"]').fill('1방울');await save(p);const d=await p.evaluate(()=>state.records[0].body.ophthalmicChart);assert.deepEqual([d.lesions[0].eye,d.lesions[0].x,d.lesions[0].widthMm,d.lesions[0].heightMm],['od',50,2,3]);assert.equal(d.prescriptions[0].eye,'os');await p.locator('[data-remove-rx]').click();await save(p);assert.equal(await p.evaluate(()=>state.records[0].body.ophthalmicChart.prescriptions.length),0);await p.close();});
test('creation and update response loss retry without duplicating records',async()=>{const p=await page();await quick(p);await p.evaluate(()=>state.loseResponse=true);await p.locator('[data-act=save]').click();await p.locator('[data-er-status]').filter({hasText:'저장 실패'}).waitFor();await save(p);assert.equal(await p.evaluate(()=>state.records.length),1);await tab(p,'plan');await p.locator('[data-field=diagnosis]').fill('검사 판단');await p.evaluate(()=>state.loseResponse=true);await p.locator('[data-act=save]').click();await p.locator('[data-er-status]').filter({hasText:'저장 실패'}).waitFor();await save(p);assert.equal(await p.evaluate(()=>state.records[0].revision),2);assert.equal(await p.locator('[data-field=diagnosis]').inputValue(),'검사 판단');await p.close();});
test('completion failure retries the same intent',async()=>{const p=await page();await begin(p);await p.evaluate(()=>state.fail=true);await p.locator('[data-act=complete]').click();await p.locator('[data-er-status]').filter({hasText:'저장 실패'}).waitFor();assert.equal(await p.locator('[data-act=complete]').innerText(),'작성 완료 저장 재시도');await p.evaluate(()=>state.fail=false);await p.locator('[data-act=complete]').click();await p.waitForFunction(()=>state.records[0].body.ophthalmicChart.clinicalStatus==='complete');assert.equal(await p.locator('[data-act=complete]').innerText(),'작성 재개');await p.close();});
test('edits made during delayed save are persisted without loss',async()=>{const p=await page();await begin(p);await p.evaluate(()=>{window.realAPI=api;api=async(path,o)=>{if(o?.method==='POST')await new Promise(r=>setTimeout(r,350));return realAPI(path,o);};});await tab(p,'plan');await p.locator('[data-field=diagnosis]').fill('처음');await p.locator('[data-act=save]').click();await tab(p,'plan');await p.locator('[data-field=diagnosis]').fill('마지막');await p.waitForFunction(()=>document.querySelector('[data-act=save]')?.textContent==='저장 완료');assert.equal(await p.evaluate(()=>state.records[0].body.ophthalmicChart.diagnosis),'마지막');await p.close();});
test('concurrent edit keeps local input and exposes explicit reconciliation',async()=>{const p=await page();await begin(p);await p.evaluate(()=>{state.records[0].revision++;state.records[0].body.ophthalmicChart.diagnosis='다른 직원 판단';});await tab(p,'plan');await p.locator('[data-field=diagnosis]').fill('내 입력');await p.locator('[data-act=save]').click();await p.locator('[data-remote]').waitFor();assert.equal(await p.locator('[data-field=diagnosis]').inputValue(),'내 입력');assert.equal(await p.locator('[data-act=save]').isDisabled(),true);await p.locator('[data-remote]').click();assert.equal(await p.locator('[data-field=diagnosis]').inputValue(),'다른 직원 판단');await p.close();});
test('recheck starts with blank findings, compares prior chart and retains exam weight',async()=>{const p=await page();await begin(p);await p.locator('[data-field="od.iop"]').fill('22');await p.locator('[data-field=weight]').fill('4');await save(p);await p.locator('[data-act=recheck]').click();assert.equal(await p.locator('[data-field="od.iop"]').inputValue(),'');assert.equal(await p.locator('[data-field=weight]').inputValue(),'4');await save(p);await tab(p,'compare');await p.locator('[data-prior]').waitFor();assert.match(await p.locator('[data-comparison]').innerText(),/22 mmHg.*미검사/s);assert.equal(await p.locator('[data-comparison] svg').count(),3);await p.close();});
test('registered comparison keeps more than twelve prior exams accessible and excludes future',async()=>{const p=await page();await registered(p);await p.evaluate(()=>{const a=state.records[0];for(let i=1;i<=15;i++){const r=structuredClone(a);r.id='prior'+i;r.body.ophthalmicChart.date='2026-10-'+String(i).padStart(2,'0');state.records.push(r);}const future=structuredClone(a);future.id='future';future.body.ophthalmicChart.date='2027-01-01';state.records.push(future);});await tab(p,'compare');await p.locator('[data-prior-more]').waitFor();assert.equal(await p.locator('[data-prior] option').count(),12);await p.locator('[data-prior-more]').click();await p.waitForFunction(()=>document.querySelectorAll('[data-prior] option').length===15);assert.doesNotMatch(await p.locator('[data-prior]').innerText(),/2027/);await p.close();});
test('photos save as bounded previews, lazy load and caption changes preserve bytes',async()=>{const p=await page();await begin(p);const buf=await p.evaluate(()=>{const c=document.createElement('canvas');c.width=100;c.height=100;c.getContext('2d').fillRect(0,0,100,100);return c.toDataURL().split(',')[1];});await tab(p,'maps');await p.locator('[data-photo]').setInputFiles({name:'synthetic.png',mimeType:'image/png',buffer:Buffer.from(buf,'base64')});await p.locator('.er-photo img').waitFor();await p.locator('[data-image="0.eye"]').selectOption('od');await p.locator('[data-image="0.caption"]').fill('합성 각막 사진');await save(p);assert.equal(await p.evaluate(()=>state.records[0].body.ophthalmicChart.images[0].dataUrl),undefined);await p.locator('[data-act=back]').click();await p.locator('[data-open]').click();await tab(p,'maps');await p.locator('.er-photo img').waitFor();assert.equal(await p.locator('[data-image="0.caption"]').inputValue(),'합성 각막 사진');await p.locator('[data-image="0.caption"]').fill('수정 설명');await save(p);assert.equal(await p.evaluate(()=>Object.keys(state.imageData).length),1);assert.equal(await p.locator('.er-photo img').evaluate(e=>e.naturalWidth),100);await p.close();});
test('invalid input is retained and blocks writes',async()=>{const p=await page();await begin(p);const n=await p.evaluate(()=>state.requests.filter(r=>r.method==='POST').length);await p.locator('[data-field="od.iop"]').fill('-1');await p.locator('[data-act=save]').click();assert.match(await p.locator('[data-er-status]').innerText(),/입력 범위/);assert.equal(await p.evaluate(()=>state.requests.filter(r=>r.method==='POST').length),n);assert.equal(await p.locator('[data-field="od.iop"]').inputValue(),'-1');await p.close();});
test('read-only view has no mutation controls and scope changes clear patient',async()=>{const p=await page();await begin(p);await p.evaluate(async()=>{view.dispose();state.canEdit=false;view=OphthalmicRecord.mount(document.querySelector('#root'),opts);await view.open();});await p.locator('[data-field="od.iop"]').waitFor();assert.equal(await p.locator('[data-act=save]').count(),0);assert.equal(await p.locator('[data-field="od.iop"]').isDisabled(),true);await p.evaluate(()=>{state.scope='other:staff';view.sync();});assert.equal(await p.locator('#root').innerText(),'');await p.close();});
test('delete affects only selected record and returns list',async()=>{const p=await page();await begin(p);await p.locator('[data-act=delete]').click();await p.locator('[data-act=new]').waitFor();assert.equal(await p.evaluate(()=>state.records[0].body.deleted),true);assert.equal(await p.locator('[data-open]').count(),0);await p.close();});
test('print includes structured bilateral exam, identity and safe text',async()=>{const p=await page();await begin(p);await p.locator('[data-field="od.stt"]').fill('12');await p.locator('[data-field="os.iop"]').fill('18');await tab(p,'plan');await p.locator('[data-field=diagnosis]').fill('<script>window.injected=true</script>');await save(p);const waiting=p.waitForEvent('popup');await p.locator('[data-act=print]').click();const out=await waiting;await out.locator('h1').waitFor();assert.match(await out.locator('body').innerText(),/우안 OD.*좌안 OS.*12 mm\/min.*18 mmHg/s);assert.equal(await out.evaluate(()=>window.injected),undefined);await out.waitForFunction(()=>[...document.fonts].some(f=>f.status==='loaded'));const pdf=await out.pdf({preferCSSPageSize:true});assert.ok(pdf.length>1000);if(process.env.EYE_SCREENSHOT_DIR)fs.writeFileSync(path.join(process.env.EYE_SCREENSHOT_DIR,'ophthalmic-synthetic.pdf'),pdf);await out.close();await p.close();});
for(const width of [320,390,768,1440])test('first screen and bilateral exam fit viewport '+width,async()=>{const p=await page(width);assert.ok(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));await begin(p);assert.ok(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));for(const s of ['od','os'])assert.ok(await p.locator('[data-field="'+s+'.iop"]').evaluate(e=>{const r=e.getBoundingClientRect();return r.width>=40&&r.left>=0&&r.right<=innerWidth;}));if(process.env.EYE_SCREENSHOT_DIR)await p.screenshot({path:path.join(process.env.EYE_SCREENSHOT_DIR,'ophthalmic-'+width+'.png'),fullPage:true});await p.close();});
test('clinical menu routes to eye chart and leaves safely without unrelated clinical fetch',async()=>{const p=await page();await p.addScriptTag({url:url+'/practice-tools.js'});await p.evaluate(async()=>{view.dispose();window.eyeOpts={...opts,patient:()=>null,navigation:()=>{}};window.practice=PracticeTools.mount(document.querySelector('#root'),eyeOpts);if(!practice.prepareTab('ophthalmic'))throw Error('route failed');await practice.open();});await p.locator('[data-act=new]').waitFor();await begin(p);await tab(p,'plan');await p.locator('[data-field=diagnosis]').fill('메뉴 이동 전 입력');await p.evaluate(async()=>{if(practice.prepareTab('intake',()=>practice.open()))await practice.open();});await p.waitForFunction(()=>practice.route()==='intake');assert.equal(await p.evaluate(()=>state.records[0].body.ophthalmicChart.diagnosis),'메뉴 이동 전 입력');await p.evaluate(async()=>{practice.prepareTab('ophthalmic');await practice.open();});await p.locator('[data-field=diagnosis]').waitFor();assert.equal(await p.locator('[data-field=diagnosis]').inputValue(),'메뉴 이동 전 입력');await p.close();});
test('full CLINIC entry exposes ophthalmic route within clinical menu',async()=>{const p=await browser.newPage({viewport:{width:1440,height:900}});p.setDefaultTimeout(10000);const issues=[];p.on('pageerror',e=>issues.push(e.message));await p.route('**/*',r=>r.request().url().startsWith(url)?r.continue():r.abort());await p.goto(url+'/index.html');await p.evaluate(()=>{saasMode='auth';saasToken='synthetic-local-token';saasSessionMeta={id:'test'};saasMe={role:'owner',clinic:{id:'a'},user:{id:'owner'}};saasRequest=async(path)=>path.includes('ophthalmic')?{items:[],next:null}:{ok:true,runs:[],templates:[],members:[],items:[],patients:[],userId:'owner',manager:true};showApp({deferFullRender:true});go('practice');});await p.waitForTimeout(300);await p.locator('[data-nav-group=clinical]').evaluate(e=>e.open=true);if(process.env.EYE_SCREENSHOT_DIR)await p.screenshot({path:path.join(process.env.EYE_SCREENSHOT_DIR,'clinic-before-eye.png')});fs.writeFileSync(path.join(root,'../ophthalmic-qa/navigation-debug.json'),JSON.stringify({issues,state:await p.evaluate(()=>({nav:typeof ClinicNavigation,practice:typeof CarestepPractice,classes:document.body.className,resources:performance.getEntriesByType('resource').filter(r=>r.responseStatus>=400).map(r=>r.name)}))}));await p.locator('.clinic-navigation [data-tab=ophthalmic]').click();await p.locator('[data-act=new]').waitFor();assert.match(await p.locator('[data-tab=ophthalmic]').getAttribute('aria-current'),/page/);assert.equal(await p.locator('body').evaluate(e=>e.classList.contains('clinic-clinical-view')),true);if(process.env.EYE_SCREENSHOT_DIR)await p.screenshot({path:path.join(process.env.EYE_SCREENSHOT_DIR,'ophthalmic-clinic-list.png'),fullPage:true});await p.close();});
test('browser writes actual encrypted server schema including photos and prescriptions',async t=>{const {pathToFileURL}=require('node:url');const wr=process.env.TRAINING_WORKER_ROOT;const {fixture}=await import(pathToFileURL(path.join(wr,'test/helpers/practice-fixture.mjs')).href),f=fixture(t);f.c.structuredClone=structuredClone;f.c.atob=atob;f.sqlite.exec(fs.readFileSync(path.join(wr,'migrations/20261026_clinical_workspace.sql'),'utf8'));f.sqlite.exec("ALTER TABLE care_patients ADD COLUMN species TEXT DEFAULT 'dog'");const p=await page();await p.route('**/test-api/**',async route=>{const req=route.request(),u=new URL(req.url());try{const out=await f.extras(u.pathname.replace('/test-api/practice','')+u.search,req.method(),req.postDataJSON()||{},f.owner);await route.fulfill({json:out});}catch(e){await route.fulfill({status:e.statusCode||500,json:{error:e.message}});}});await p.evaluate(()=>{api=async(p,o={})=>{const r=await fetch('/test-api'+p,o),d=await r.json();if(!r.ok)throw Object.assign(Error(d.error),{status:r.status});return d;};});await quick(p);await p.locator('[data-field="od.stt"]').fill('12');await p.locator('[data-field="od.pupilSize"]').selectOption('dilated');await p.locator('[data-field="os.pupilSize"]').selectOption('normal');await tab(p,'plan');await p.locator('[data-act=add-rx]').click();await p.locator('[data-rx="0.eye"]').selectOption('od');await p.locator('[data-rx="0.name"]').fill('시험 약물');await p.locator('.er-rx-templates>summary').click();await p.locator('[data-template-title]').fill('서버 연동 서식');await p.locator('[data-template-save]').click();await p.waitForFunction(()=>document.querySelectorAll('[data-template] option').length===2);assert.equal((await f.extras('/clinical/workflows','GET',{},f.owner)).items[0].body.prescriptions[0].name,'시험 약물');const buf=await p.evaluate(()=>{const c=document.createElement('canvas');c.width=50;c.height=50;return c.toDataURL().split(',')[1];});await tab(p,'maps');await p.locator('[data-photo]').setInputFiles({name:'synthetic.png',mimeType:'image/png',buffer:Buffer.from(buf,'base64')});await p.locator('.er-photo img').waitFor();await save(p);const list=await f.extras('/clinical/ophthalmic','GET',{},f.owner);assert.equal(list.items.length,1);const id=list.items[0].id,r=await f.extras('/clinical/cases/'+id+'?view=ophthalmic','GET',{},f.owner);assert.equal(r.item.body.ophthalmicChart.od.stt,12);assert.equal(r.item.body.ophthalmicChart.od.pupilSize,'dilated');assert.equal(r.item.body.ophthalmicChart.os.pupilSize,'normal');assert.equal(r.item.body.ophthalmicChart.prescriptions[0].eye,'od');assert.equal(r.item.body.ophthalmicChart.images[0].imageRevision,1);await tab(p,'plan');await p.locator('[data-act=add-rx]').click();await p.locator('[data-rx="1.name"]').fill('미완성 서버검증');await tab(p,'tests');await p.locator('[data-field="od.iop"]').fill('24');await p.locator('[data-act=save]').click();await p.waitForFunction(()=>document.querySelector('[data-act=save]').textContent==='검사 저장 완료');const partial=await f.extras('/clinical/cases/'+id+'?view=ophthalmic','GET',{},f.owner);assert.equal(partial.item.body.ophthalmicChart.od.iop,24);assert.equal(partial.item.body.ophthalmicChart.prescriptions.length,1);await tab(p,'plan');await p.locator('[data-remove-rx="1"]').click();await save(p);await tab(p,'maps');await p.locator('[data-remove-image]').click();await save(p);assert.equal((await f.extras('/clinical/cases/'+id+'?view=ophthalmic','GET',{},f.owner)).item.body.ophthalmicChart.images.length,0);await p.locator('[data-undo-delete]').click();await save(p);assert.equal((await f.extras('/clinical/cases/'+id+'?view=ophthalmic','GET',{},f.owner)).item.body.ophthalmicChart.images.length,1);await p.locator('[data-act=back]').click();await p.locator('[data-open]').click();await tab(p,'maps');await p.locator('.er-photo img').waitFor();assert.ok(await p.locator('.er-photo img').evaluate(e=>e.naturalWidth>0));await tab(p,'tests');await p.locator('[data-field="os.iop"]').fill('16');await save(p);await p.locator('[data-act=complete]').click();await p.waitForFunction(()=>document.querySelector('[data-er-state]').textContent==='작성 완료');await p.locator('[data-act=recheck]').click();assert.equal(await p.locator('[data-field="od.stt"]').inputValue(),'');await save(p);assert.equal((await f.extras('/clinical/ophthalmic','GET',{},f.owner)).items.length,2);await p.close();});

