test('compact examination uses columns on PC, paired eyes on mobile and no device editor',async()=>{
 for(const [width,columns] of [[1700,3],[1200,2],[390,1],[320,1]]){
  const p=await page(width);await quick(p);
  const grid=p.locator('[data-exam-group=basic] .er-exam-grid');
  assert.equal(await grid.evaluate(e=>getComputedStyle(e).gridTemplateColumns.split(' ').length),columns);
  assert.equal(await p.locator('[data-field="od.device"]').count(),0);
  assert.equal(await p.locator('[data-field="os.measuredAt"]').count(),0);
  assert.ok(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));
  assert.equal(await p.locator('[data-exam-group=basic] .er-eye-labels').count(),3);
  if(width<760)assert.ok(await p.locator('[data-field="od.iop"]').evaluate(e=>getComputedStyle(e).fontSize==='16px'&&e.getBoundingClientRect().height>=44));
  if(process.env.EYE_SCREENSHOT_DIR)await p.screenshot({path:path.join(process.env.EYE_SCREENSHOT_DIR,'compact-exam-'+width+'.png'),fullPage:true});
  await p.close();
 }
});
